-- 2026-11-11 1.3 修正块 id 重复，并将 I/O 总线相关条目上移
begin;
create temp table _kbid(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kbid(node_id, blocks, search_text) values
(48, $kbid$[{"t":"list","id":"a1-1-3-1-b1","imp":"core","items":["1、==PC 机组成==：主板（芯片组、BISO、CMOS、PCI 插槽等）、机箱电源、==CPU==、==内存条==、声卡、网卡、显卡、插头（插座接口）、==输入设备==、==输出设备==（显示器、打印机、音箱/耳机）、==外存==（硬盘、软驱、光驱、移动硬盘、U 盘等）等。","为了便于不同PC 机主板的互换，主板的物理尺寸已经标准化，目前使用的比较多的是ATX 规格的主板。","2、==主板：又称母板。计算机最重要的部件之一。主板一般为矩形电路板，上面安装了组成计算机的主要电路系统，一般有BIOS 芯片、I/O 控制芯片、键盘和面板控制开关接口、指示灯插接件、扩充插槽、主板及插卡的直流电源供电接插件等元件。==","3、主板的作用：安装所有电子器件、电路与连接件","4、==主板的组成部件==：==主板又称母板==，通常安装有CPU插座、CPU调压器、芯片组、第2级高速缓存（有的已做在CPU中）、存储器插槽（SIMM或DIMM）、总线插槽（如PCI-E、AGP）、接口（IDE并口、SATA）、ROM BIOS、时钟/CMOS、电池、超级I/O芯片等。","5、芯片组：是主板电路的核心部件，集中了几乎主板上所有控制功能，决定了主板的档次和级别。","6、芯片组是PC 机各组成部分相互连接和通信的枢纽，实现了系统总线功能。","7、芯片组决定主板能安装的 CPU 的类型、主频。","8、芯片组决定主板能安装的主存的最大容量、速度和可使用的内存条的类型。","9、==芯片组是由南桥芯片和北桥芯片构成==，一般芯片组的结构图如下所示："],"title":"","ordered":false},{"h":728,"t":"img","w":1228,"id":"a1-1-3-1-b2","imp":"normal","src":"/kb-assets/theory/p10_r0_0d4a147031da44c2.png","title":""},{"t":"list","id":"a1-1-3-1-b3","imp":"core","items":["10、==南桥芯片功能==：","（1）==I/O 控制中心==","（2）==主要与 PCl 总线槽、USB 接口、硬盘接口、音频解码器、 BIOS 和CMOS 存储器等连接，并借助Super I/O 芯片提供对鼠标键盘、串行口、并行口等的控制。==","11、==北桥芯片功能（目前大部功能都集成到CPU 芯片中处理）==：","（1）==存储控制中心==","（2）==高速连接CPU、存储器、显卡、并且是连接南桥芯片的枢纽==","12、^^现在很多 I/O 控制器都不以扩展卡的形式出现。南桥芯片中已经集成了I/O 控制器的功能。^^","13、==芯片组与 BIOS 的补充说明==：芯片组与 CPU 芯片同步发展，有什么样功能和速度的 CPU，就有什么样的芯片组与之配套。由于集成电路集成度越来越高，为降低系统成本，芯片组中集成了越来越多的功能，包括==网卡、显卡、声卡等功能==。由于 CPU 芯片越来越复杂、功能越来越强大（如 Core i3/i5/i7），有些已将北桥芯片的存储器控制器和图形控制器功能集成在 CPU 芯片之中，因此主板上北桥芯片已经消失，只需一块南桥芯片即可。","14、==BIOS（Basic Input/Output System）==：中文名为==基本输入/输出系统==，是存放在主板上只读存储器（ROM）芯片中的一组机器语言程序。","15、==内存容量是计算机的性能指标==：==内存容量属于计算机的性能指标之一==，会影响计算机性能。一般所说的“存储容量是计算机的性能指标”，这里的存储容量指的就是内存容量。","16、==内存容量及其影响因素==：==容量以MB为单位==，指所有存储单元的总数。 存储单元：每个存储单元就是一个字节、一个地址，CPU访问内存就是寻址，内存存储单元的基本单位是字节。 内存容量主要受主板芯片组、内存插槽及CPU地址总线宽度（位数）的影响。 CPU可寻址空间的大小由地址线宽度决定。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-3-1-b4","imp":"core","kind":"tip","text":"现代主流 Intel 和 AMD 处理器已将传统北桥芯片的==内存控制器（IMC）和 PCI-E 图形控制器直接完全集成在 CPU 芯片内部==，主板仅保留单芯片 PCH（平台控制器中心，即南桥演进），负责管理 SATA、USB、板载声卡网卡与低速总线通道。","title":"考向复习提示：主板芯片组架构演进趋势"},{"t":"callout","id":"a1-1-3-1-b5","imp":"core","kind":"trap","text":"专转本必考概念辨析：==BIOS 是固化在只读存储器（ROM/Flash ROM）中的一组固件系统软件==（包含 POST 加电自检、系统初始化与引导程序）；而 ==CMOS 是随机存取存储器（RAM）==，仅用于存储时间与硬件配置参数，需纽扣电池供电，断电数据丢失；切勿混淆两者的介质类型与功能！","title":"高频易错陷阱：BIOS 与 CMOS 的本质区别"}]$kbid$::jsonb, $kbidse$A1-1.3.1 主板、芯片组、BIOS、内存储器概述，I/O 总线和 I/O 接口。 1、PC 机组成：主板（芯片组、BISO、CMOS、PCI 插槽等）、机箱电源、CPU、内存条、声卡、网卡、显卡、插头（插座接口）、输入设备、输出设备（显示器、打印机、音箱/耳机）、外存（硬盘、软驱、光驱、移动硬盘、U 盘等）等。 为了便于不同PC 机主板的互换，主板的物理尺寸已经标准化，目前使用的比较多的是ATX 规格的主板。 2、主板：又称母板。计算机最重要的部件之一。主板一般为矩形电路板，上面安装了组成计算机的主要电路系统，一般有BIOS 芯片、I/O 控制芯片、键盘和面板控制开关接口、指示灯插接件、扩充插槽、主板及插卡的直流电源供电接插件等元件。 3、主板的作用：安装所有电子器件、电路与连接件 4、主板的组成部件：主板又称母板，通常安装有CPU插座、CPU调压器、芯片组、第2级高速缓存（有的已做在CPU中）、存储器插槽（SIMM或DIMM）、总线插槽（如PCI-E、AGP）、接口（IDE并口、SATA）、ROM BIOS、时钟/CMOS、电池、超级I/O芯片等。 5、芯片组：是主板电路的核心部件，集中了几乎主板上所有控制功能，决定了主板的档次和级别。 6、芯片组是PC 机各组成部分相互连接和通信的枢纽，实现了系统总线功能。 7、芯片组决定主板能安装的 CPU 的类型、主频。 8、芯片组决定主板能安装的主存的最大容量、速度和可使用的内存条的类型。 9、芯片组是由南桥芯片和北桥芯片构成，一般芯片组的结构图如下所示： 10、南桥芯片功能： （1）I/O 控制中心 （2）主要与 PCl 总线槽、USB 接口、硬盘接口、音频解码器、 BIOS 和CMOS 存储器等连接，并借助Super I/O 芯片提供对鼠标键盘、串行口、并行口等的控制。 11、北桥芯片功能（目前大部功能都集成到CPU 芯片中处理）： （1）存储控制中心 （2）高速连接CPU、存储器、显卡、并且是连接南桥芯片的枢纽 12、现在很多 I/O 控制器都不以扩展卡的形式出现。南桥芯片中已经集成了I/O 控制器的功能。 13、芯片组与 BIOS 的补充说明：芯片组与 CPU 芯片同步发展，有什么样功能和速度的 CPU，就有什么样的芯片组与之配套。由于集成电路集成度越来越高，为降低系统成本，芯片组中集成了越来越多的功能，包括网卡、显卡、声卡等功能。由于 CPU 芯片越来越复杂、功能越来越强大（如 Core i3/i5/i7），有些已将北桥芯片的存储器控制器和图形控制器功能集成在 CPU 芯片之中，因此主板上北桥芯片已经消失，只需一块南桥芯片即可。 14、BIOS（Basic Input/Output System）：中文名为基本输入/输出系统，是存放在主板上只读存储器（ROM）芯片中的一组机器语言程序。 15、内存容量是计算机的性能指标：内存容量属于计算机的性能指标之一，会影响计算机性能。一般所说的“存储容量是计算机的性能指标”，这里的存储容量指的就是内存容量。 16、内存容量及其影响因素：容量以MB为单位，指所有存储单元的总数。 存储单元：每个存储单元就是一个字节、一个地址，CPU访问内存就是寻址，内存存储单元的基本单位是字节。 内存容量主要受主板芯片组、内存插槽及CPU地址总线宽度（位数）的影响。 CPU可寻址空间的大小由地址线宽度决定。 考向复习提示：主板芯片组架构演进趋势 现代主流 Intel 和 AMD 处理器已将传统北桥芯片的内存控制器（IMC）和 PCI-E 图形控制器直接完全集成在 CPU 芯片内部，主板仅保留单芯片 PCH（平台控制器中心，即南桥演进），负责管理 SATA、USB、板载声卡网卡与低速总线通道。 高频易错陷阱：BIOS 与 CMOS 的本质区别 专转本必考概念辨析：BIOS 是固化在只读存储器（ROM/Flash ROM）中的一组固件系统软件（包含 POST 加电自检、系统初始化与引导程序）；而 CMOS 是随机存取存储器（RAM），仅用于存储时间与硬件配置参数，需纽扣电池供电，断电数据丢失；切勿混淆两者的介质类型与功能！$kbidse$),(49, $kbid$[{"t":"list","id":"a1-1-3-2-b1","imp":"core","items":["1、^^BIOS（基本输入/输出系统）^^","（1）^^BIOS: Basic Input/Output System,即“基本输入/输出系统”^^，存放在主板上只读存储器（ROM）芯片中的一组机器语言程序（==固件，二进制语言程序，属于系统软件==）。","（2）特点：^^断电后保存的信息不会消失^^","（3）功能作用：","^^①开机时诊断计算机故障（比如出现蓝屏）^^","^^②启动计算机工作^^","^^③启动阶段控制外设基本输入输出操作（键盘、鼠标、磁盘读写、屏幕显示等）^^","（4）==组成==：","①==加电自检程序（POST）==：检测计算机硬件故障","②==系统自举程序（Boot）==：启动计算机，加载并进入操作系统运行态","③==CMOS 设置程序==：设置系统参数（日期、时间、口令等）","④==常用外部设备的驱动程序==：启动阶段对基本外设输入输出操作","（5）计算机启动顺序：POST->引导装入程序（自举程序）->引导程序->操作系统。","2、CMOS","（1）CMOS:互补金属氧化物半导体","（2）CMOS 芯片是主板上的一块RAM（随机存取存储器）。","（3）^^CMOS 存放计算机一些基本参数（日期、时间、硬件启动顺序等），可以被修改。^^","（4）==通过BIOS 设置程序对CMOS 参数进行设置与修改。==","（5）==断电后CMOS 中的信息会丢失，所以CMOS 芯片须由主板上的电池供电，来保证其在计算机断电后信息不会丢失。==","（6）==CMOS 中存储的是硬件设置参数==：==CMOS 中存储的是用户对计算机硬件的设置参数==，一般添加新硬件或优化开机时才设置 CMOS。在 CMOS 中可以设置系统时间、启动顺序、病毒检测、即插即用设备、开机密码及 CMOS 密码、磁盘驱动器数量等。","3、内存储器","（1）计算机存储器分为两类：内存储器和外存储器。","（2）==内存和外存的区别==：","==①、内存存取速度快、容量小、成本高，大都是易失性存储器（临时存放正在运行的程序和数据）；外存存取速度慢，容量大，成本低，断电后信息不会丢失（文件长久存放系统中）。==","==②、内存都是由半导体芯片构成的；外存的存储介质有：磁表面存储顺（硬盘），半导体芯片（U 盘）。==","==③、内存按字节编址和存取；外存按数据块编址和存取。==","==④、内存直接与CPU 连接，CPU（指令）可以对内存中指及数据进行读、写操作；外存不与CPU 直接连接，外存中的程序及相关数据需要先传递至内存中后才能被CPU 使用。==","（3）内存容量：内存容量的大小对CPU 的速度几乎不存在影响，内存容量大小是计算机性能的指标之一。","单位：MB 或GB。","（4）存取时间：从CPU 送出内存单元的地址码开始，到主存读出数据并送到CPU（或者是把CPU 数据写入主存）所需要的时间（单位：ns（纳秒），1 ns = 10⁻⁹ s）。","4、半导体存储器","（1）分类：^^RAM（随机存储器）^^和^^ROM（只读存储器）^^","（2）^^随机存储器（RAM）:SRAM（静态随机存储器）和DRAM(动态随机存储器)^^","==①、SRAM：不需要刷新，读写速度较快；电路相对复杂，集成度低，能耗高，成本较高；一般用于Cache 存储器。==","==②、DRAM：每10~100ms 刷新一次，读写速度较慢，电路相对简单，集成度高，能耗低，成本较低；一般用于主存。==","（3）只读存储器（ROM）:EEPROM(带电可擦可编程只读存储器)和==Flash ROM（闪速存储器）==","①、EEPROM：非易失性存储器，断电后信息不会丢失，速度较慢，容量不大，价格便宜，在低端产品中用的较多。","②、==Flash ROM：非易失性存储器，断电后信息不会丢失，高电压可写，低电压可读。或非型（NOR）==","==flash，可以用作内存储器（例如存储BIOS程序的flash存储器）；与非型（NAND）flash,可以用于数据码相机存储卡、固态硬盘、U盘，智能手机中“机身存储或手机存储”等。==","5、==内存容量与存储器速度排序==：PC 机中用户实际可用的内存容量通常指 RAM 的容量。 RAM 能够直接与外存交换数据。 计算机中存储器速度由快到慢：CPU → 寄存器 → Cache → 内存 → 外存储器（软盘、硬盘、光盘）→ 后备存储器（磁带库、光盘库）。","6、==存储器的层次结构与工作过程==","（1）速度越快，成本较高。 为了获得好的性能/价格比，计算机中各种存储器组成一个层状的塔式结构，取长补短，协调工作。","（2）工作过程：","①、^^CPU 运行时，需要的操作数大部分来自寄存器^^","②、^^如需要从(向)存储器中取(存) 数据时，先访问cache，如在，取自cache^^","③、^^如操作数不在cache，则访问RAM，如在RAM 中，则取自RAM^^","④、^^如操作数不在RAM，则访问硬盘，操作数从硬盘中读出→RAM →cache^^"],"title":"","ordered":false},{"h":546,"t":"img","w":1398,"id":"a1-1-3-2-b2","imp":"normal","src":"/kb-assets/theory/p12_r1_3112a1f6861ffe8b.png","title":""},{"t":"list","id":"a1-1-3-2-b3","imp":"core","items":["7、==DRAM 主存储器与内存条==：主存储器主要由 ==DRAM 芯片组成==，包含大量存储单元，每个存储单元可以存放 1 个字节（8 个二进制位）。存储器的存储容量就是它所包含的存储单元的总和。每个存储单元都有一个地址，CPU 按地址对存储器进行访问。 存储器的存取时间指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间，主存储器存取时间的单位是 ns（1 ns 10⁻⁹ 秒）。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-3-2-b4","imp":"core","kind":"tip","text":"内存储器两大核心：==RAM（SRAM 用于 Cache 速度快成本高；DRAM 用于主存需动态刷新）==；==ROM（Mask ROM、PROM、EPROM、EEPROM/Flash ROM）==；计算机开机流程：加电→==CPU 执行 BIOS 中的 POST 加电自检==→初始化设备→加载引导扇区（MBR/GPT）→将 OS 内核载入内存启动。","title":"考向复习提示：RAM 与 ROM 各种类型及开机流程"},{"t":"callout","id":"a1-1-3-2-b5","imp":"core","kind":"trap","text":"==SRAM 依靠双稳态触发器存储信息==，只要通电信息不丢失，不需刷新；而 ==DRAM 依靠微型电容上的电荷存储信息==，电容存在漏电现象，电荷会在数毫秒内自然漏掉，因此==必须由内存控制器每隔数毫秒定期执行动态刷新（充电）操作==；考试常考混淆两者的内部结构与是否需要刷新。","title":"高频易错陷阱：DRAM 为什么必须定期刷新？"}]$kbid$::jsonb, $kbidse$A1-1.3.2 BIOS 组成及运行过程，内存储器 RAM 和 ROM 各种类型。 1、BIOS（基本输入/输出系统） （1）BIOS: Basic Input/Output System,即“基本输入/输出系统”，存放在主板上只读存储器（ROM）芯片中的一组机器语言程序（固件，二进制语言程序，属于系统软件）。 （2）特点：断电后保存的信息不会消失 （3）功能作用： ①开机时诊断计算机故障（比如出现蓝屏） ②启动计算机工作 ③启动阶段控制外设基本输入输出操作（键盘、鼠标、磁盘读写、屏幕显示等） （4）组成： ①加电自检程序（POST）：检测计算机硬件故障 ②系统自举程序（Boot）：启动计算机，加载并进入操作系统运行态 ③CMOS 设置程序：设置系统参数（日期、时间、口令等） ④常用外部设备的驱动程序：启动阶段对基本外设输入输出操作 （5）计算机启动顺序：POST->引导装入程序（自举程序）->引导程序->操作系统。 2、CMOS （1）CMOS:互补金属氧化物半导体 （2）CMOS 芯片是主板上的一块RAM（随机存取存储器）。 （3）CMOS 存放计算机一些基本参数（日期、时间、硬件启动顺序等），可以被修改。 （4）通过BIOS 设置程序对CMOS 参数进行设置与修改。 （5）断电后CMOS 中的信息会丢失，所以CMOS 芯片须由主板上的电池供电，来保证其在计算机断电后信息不会丢失。 （6）CMOS 中存储的是硬件设置参数：CMOS 中存储的是用户对计算机硬件的设置参数，一般添加新硬件或优化开机时才设置 CMOS。在 CMOS 中可以设置系统时间、启动顺序、病毒检测、即插即用设备、开机密码及 CMOS 密码、磁盘驱动器数量等。 3、内存储器 （1）计算机存储器分为两类：内存储器和外存储器。 （2）内存和外存的区别： ①、内存存取速度快、容量小、成本高，大都是易失性存储器（临时存放正在运行的程序和数据）；外存存取速度慢，容量大，成本低，断电后信息不会丢失（文件长久存放系统中）。 ②、内存都是由半导体芯片构成的；外存的存储介质有：磁表面存储顺（硬盘），半导体芯片（U 盘）。 ③、内存按字节编址和存取；外存按数据块编址和存取。 ④、内存直接与CPU 连接，CPU（指令）可以对内存中指及数据进行读、写操作；外存不与CPU 直接连接，外存中的程序及相关数据需要先传递至内存中后才能被CPU 使用。 （3）内存容量：内存容量的大小对CPU 的速度几乎不存在影响，内存容量大小是计算机性能的指标之一。 单位：MB 或GB。 （4）存取时间：从CPU 送出内存单元的地址码开始，到主存读出数据并送到CPU（或者是把CPU 数据写入主存）所需要的时间（单位：ns（纳秒），1 ns = 10⁻⁹ s）。 4、半导体存储器 （1）分类：RAM（随机存储器）和ROM（只读存储器） （2）随机存储器（RAM）:SRAM（静态随机存储器）和DRAM(动态随机存储器) ①、SRAM：不需要刷新，读写速度较快；电路相对复杂，集成度低，能耗高，成本较高；一般用于Cache 存储器。 ②、DRAM：每10~100ms 刷新一次，读写速度较慢，电路相对简单，集成度高，能耗低，成本较低；一般用于主存。 （3）只读存储器（ROM）:EEPROM(带电可擦可编程只读存储器)和Flash ROM（闪速存储器） ①、EEPROM：非易失性存储器，断电后信息不会丢失，速度较慢，容量不大，价格便宜，在低端产品中用的较多。 ②、Flash ROM：非易失性存储器，断电后信息不会丢失，高电压可写，低电压可读。或非型（NOR） flash，可以用作内存储器（例如存储BIOS程序的flash存储器）；与非型（NAND）flash,可以用于数据码相机存储卡、固态硬盘、U盘，智能手机中“机身存储或手机存储”等。 5、内存容量与存储器速度排序：PC 机中用户实际可用的内存容量通常指 RAM 的容量。 RAM 能够直接与外存交换数据。 计算机中存储器速度由快到慢：CPU → 寄存器 → Cache → 内存 → 外存储器（软盘、硬盘、光盘）→ 后备存储器（磁带库、光盘库）。 6、存储器的层次结构与工作过程 （1）速度越快，成本较高。 为了获得好的性能/价格比，计算机中各种存储器组成一个层状的塔式结构，取长补短，协调工作。 （2）工作过程： ①、CPU 运行时，需要的操作数大部分来自寄存器 ②、如需要从(向)存储器中取(存) 数据时，先访问cache，如在，取自cache ③、如操作数不在cache，则访问RAM，如在RAM 中，则取自RAM ④、如操作数不在RAM，则访问硬盘，操作数从硬盘中读出→RAM →cache 7、DRAM 主存储器与内存条：主存储器主要由 DRAM 芯片组成，包含大量存储单元，每个存储单元可以存放 1 个字节（8 个二进制位）。存储器的存储容量就是它所包含的存储单元的总和。每个存储单元都有一个地址，CPU 按地址对存储器进行访问。 存储器的存取时间指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间，主存储器存取时间的单位是 ns（1 ns 10⁻⁹ 秒）。 考向复习提示：RAM 与 ROM 各种类型及开机流程 内存储器两大核心：RAM（SRAM 用于 Cache 速度快成本高；DRAM 用于主存需动态刷新）；ROM（Mask ROM、PROM、EPROM、EEPROM/Flash ROM）；计算机开机流程：加电→CPU 执行 BIOS 中的 POST 加电自检→初始化设备→加载引导扇区（MBR/GPT）→将 OS 内核载入内存启动。 高频易错陷阱：DRAM 为什么必须定期刷新？ SRAM 依靠双稳态触发器存储信息，只要通电信息不丢失，不需刷新；而 DRAM 依靠微型电容上的电荷存储信息，电容存在漏电现象，电荷会在数毫秒内自然漏掉，因此必须由内存控制器每隔数毫秒定期执行动态刷新（充电）操作；考试常考混淆两者的内部结构与是否需要刷新。$kbidse$),(50, $kbid$[{"t":"list","id":"a1-1-3-3-b1","imp":"core","items":["1、DDR 内存数据传输率计算:","①、==数据传输率即内存带宽，指单位时间内通过内存的数据量，单位以GB/s 表示。==","②、计算公式：@@内存带宽=工作频率X 位宽/8@@。","2、内存条的封装：目前内存的封装方式主要有TSOP、BGA、CSP 等三种，封装方式也影响着内存条的性能优劣。","3、内存地址：","==①、内存中是每一个字节都赋予唯一的编号 ，称为==@@地址@@","==②、操作系统使用==@@地址@@==对内存进行管理==","==③、内存的==@@地址@@==从0 开始编址=="],"title":"","ordered":false},{"h":271,"t":"img","w":312,"id":"a1-1-3-3-b2","imp":"normal","src":"/kb-assets/theory/p12_r0_bd4485098f4693c6.png","title":""},{"t":"list","id":"a1-1-3-3-b3","imp":"core","items":["④、内存寻址范围取决于地址线位数的多少（n），即受地址位数的限制。可寻址空间为2^n字节。"],"title":"","ordered":false},{"t":"list","id":"a1-1-3-3-b4","imp":"core","items":["4、DDR3 和DDR4","①、均采用双排直插式，其触点分布在内存条的两面","②、PC 主板上一般配有两个或四个内存条插槽","5、==内存容量与存取时间==：内存编址单位为B（字节），内存采用连续编址。CPU总线上的信号种类包括==地址信号、控制信号和数据信号==。 访问内存空间的大小： 最大访问内存空间2的地址线根数次方B。 最大访问内存空间2的最大末地址位数次方B。 例如CPU访问内存，最大末地址为3FFFFFFFH，则CPU能够访问到的最大内存空间为1024MB。 从首地址开始访问到某个地址结束时，访问内存空间地址码十进制值+1B。 存取周期：从上一次存取到下一次存取的时间间隔。 存取时间：从CPU送出地址码后，到内存中取到（存入）数据并送回到CPU所花费的时间。","6、==PC机主存储器的物理结构==：==主存储器由1～4个内存条组成==。内存条由若干片DRAM芯片焊装在一小条印制电路板上制成，必须插在主板的内存条插槽中才能使用。 目前流行的是DDR4和DDR3内存条，均采用双列直插式，触点分布在内存条的两面。DDR2和DDR3均有240个引脚，但不可互换使用。PC机主板一般配备2个或4个内存条插槽。","7、==SDRAM 与 DDR 内存条的区别==：==SDRAM通常采用168线的DIMM内存条==，DDR、DDR2、DDR3也采用双列直插式DIMM内存条，触点分布在内存条的两面。一个时钟周期内，SDRAM只能传送1次数据，DDR为2次，DDR2为4次，DDR3为8次。","8、==存取时间==：^^存取时间^^：==地址被选定后==，读出数据并将数据送入CPU的时间，或CPU向内存写入数据的时间。","9、==内存条最大存储容量==：==若内存条的地址访问线（地址访问位数）为32根==，则该内存条的最大存储容量为2的32次方Byte，即4GB。","10、^^DDR SDRAM 参数与带宽计算^^：==内存有三种不同的频率指标==：^^核心频率、时钟频率和有效数据传输频率^^。核心频率即内存Cell阵列的工作频率，是内存的真实运行频率；时钟频率即I/O Buffer（输入/输出缓存）的传输频率；有效数据传输频率是数据传送的频率。 DDR SDRAM的各项参数：以标称DDR3 1066的内存条为例，计算默认频率下的带宽。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-3-3-b5","imp":"core","kind":"tip","text":"==内存带宽（Byte/s） = 等效数据传输频率（Hz） × 数据总线位宽（bit） ÷ 8== • PC 台式机单根内存条标准数据位宽为 ==64 位（即 8 字节）==； • 因此单通道内存带宽简写为：==内存带宽（MB/s） = 等效传输频率（MHz） × 8 字节==； • 若开启==双通道内存模式==，总数据位宽翻倍为 128 位，带宽相应乘以 2。","title":"考向复习提示：内存数据传输带宽黄金计算公式"},{"t":"callout","id":"a1-1-3-3-b6","imp":"core","kind":"trap","text":"DDR SDRAM 是在时钟信号的==上升沿和下降沿均传输数据（双倍速率）==；题目中如果给出的是 DDR4-3200，其 3200 是指==等效数据传输频率为 3200 MT/s（或等效 3200 MHz）==，而不是实际核心物理频率（实际核心频率仅为 400 MHz，4 倍预取与双沿传输）；计算带宽时务必使用==等效传输频率 3200==代入公式！","title":"高频易错陷阱：核心工作频率 vs 等效传输频率"}]$kbid$::jsonb, $kbidse$A1-1.3.3 DDR SDRAM 各项参数，数据传输率计算，内存条封装形式。 1、DDR 内存数据传输率计算: ①、数据传输率即内存带宽，指单位时间内通过内存的数据量，单位以GB/s 表示。 ②、计算公式：内存带宽=工作频率X 位宽/8。 2、内存条的封装：目前内存的封装方式主要有TSOP、BGA、CSP 等三种，封装方式也影响着内存条的性能优劣。 3、内存地址： ①、内存中是每一个字节都赋予唯一的编号 ，称为地址 ②、操作系统使用地址对内存进行管理 ③、内存的地址从0 开始编址 ④、内存寻址范围取决于地址线位数的多少（n），即受地址位数的限制。可寻址空间为2^n字节。 4、DDR3 和DDR4 ①、均采用双排直插式，其触点分布在内存条的两面 ②、PC 主板上一般配有两个或四个内存条插槽 5、内存容量与存取时间：内存编址单位为B（字节），内存采用连续编址。CPU总线上的信号种类包括地址信号、控制信号和数据信号。 访问内存空间的大小： 最大访问内存空间2的地址线根数次方B。 最大访问内存空间2的最大末地址位数次方B。 例如CPU访问内存，最大末地址为3FFFFFFFH，则CPU能够访问到的最大内存空间为1024MB。 从首地址开始访问到某个地址结束时，访问内存空间地址码十进制值+1B。 存取周期：从上一次存取到下一次存取的时间间隔。 存取时间：从CPU送出地址码后，到内存中取到（存入）数据并送回到CPU所花费的时间。 6、PC机主存储器的物理结构：主存储器由1～4个内存条组成。内存条由若干片DRAM芯片焊装在一小条印制电路板上制成，必须插在主板的内存条插槽中才能使用。 目前流行的是DDR4和DDR3内存条，均采用双列直插式，触点分布在内存条的两面。DDR2和DDR3均有240个引脚，但不可互换使用。PC机主板一般配备2个或4个内存条插槽。 7、SDRAM 与 DDR 内存条的区别：SDRAM通常采用168线的DIMM内存条，DDR、DDR2、DDR3也采用双列直插式DIMM内存条，触点分布在内存条的两面。一个时钟周期内，SDRAM只能传送1次数据，DDR为2次，DDR2为4次，DDR3为8次。 8、存取时间：存取时间：地址被选定后，读出数据并将数据送入CPU的时间，或CPU向内存写入数据的时间。 9、内存条最大存储容量：若内存条的地址访问线（地址访问位数）为32根，则该内存条的最大存储容量为2的32次方Byte，即4GB。 10、DDR SDRAM 参数与带宽计算：内存有三种不同的频率指标：核心频率、时钟频率和有效数据传输频率。核心频率即内存Cell阵列的工作频率，是内存的真实运行频率；时钟频率即I/O Buffer（输入/输出缓存）的传输频率；有效数据传输频率是数据传送的频率。 DDR SDRAM的各项参数：以标称DDR3 1066的内存条为例，计算默认频率下的带宽。 考向复习提示：内存数据传输带宽黄金计算公式 内存带宽（Byte/s） = 等效数据传输频率（Hz） × 数据总线位宽（bit） ÷ 8 • PC 台式机单根内存条标准数据位宽为 64 位（即 8 字节）； • 因此单通道内存带宽简写为：内存带宽（MB/s） = 等效传输频率（MHz） × 8 字节； • 若开启双通道内存模式，总数据位宽翻倍为 128 位，带宽相应乘以 2。 高频易错陷阱：核心工作频率 vs 等效传输频率 DDR SDRAM 是在时钟信号的上升沿和下降沿均传输数据（双倍速率）；题目中如果给出的是 DDR4-3200，其 3200 是指等效数据传输频率为 3200 MT/s（或等效 3200 MHz），而不是实际核心物理频率（实际核心频率仅为 400 MHz，4 倍预取与双沿传输）；计算带宽时务必使用等效传输频率 3200代入公式！$kbidse$),(51, $kbid$[{"t":"list","id":"a1-1-3-4-b1","imp":"core","items":["1、==I/O 操作的任务、特点与注意点==","^^1）任务^^：==将输入设备输入的信息送入内存的指定区域==，或者将内存指定的内容送出到输出设备。","2）特点：","① ==I/O 设备速度比 CPU 慢==，为提高系统效率，I/O 操作与 CPU 的数据处理操作是并行的；","② 多个 I/O 设备能同时工作（例如一面键盘输入、一面屏幕显示，同时进行打印输出等）；","③ ==I/O 设备的种类多、性能相差很大==，与计算机主机的连接方法也各不相同。","3）注意：每个（类）I/O 设备都有各自专用的控制器，它们的任务是接收 CPU 启动 I/O 操作的命令后，独立地控制 I/O 操作的全过程。","2、==I/O 接口==","（1）==串行：一次传输1 位数据；串行的传输速度不一定小于并行的传输速度.（COM 接口，USB）==","（2）==并行：一次传输8 位（或16 位、32 位）数据。(如LPT 接口打印机或扫描仪、DVI、MIDI、VGA)==","（3）==独占式：只能外接1 个设备（DVI、MIDI 等）==","（4）==总线式：可以扩展多个设备。（USB 等）==","3、==I/O 控制器==","（1）==I/O 控制器是用于实现CPU 对设备的控制部件。==","（2）==I/O 控制器是控制计算机输入输出的一个最基本的控制系统，可指挥计算机的各个部件按照指令的功能要求协调工作的部件。==","（3）组成：^^指令寄存器IR、程序计数器PC、操作控制器OC^^。","（4）I/O 控制器的功能：","①、^^接收设备CPU 指令：CPU 的读写指令和参数存储在控制寄存器中^^","②、^^向CPU 报告设备的状态：I/O 控制器中会有相应的状态寄存器，用于记录I/O 设备的当前状态。^^（比如1 代表设备忙碌，0 代表设备就绪）","③、^^数据交换：数据寄存器，暂存CPU 发来的数据和设备发来的数据，之后将数据发给控制寄存器或CPU。^^","④、^^地址识别：类似于内存的地址，为了区分设备控制器中的各个寄存器，需要给各个寄存器设置一个特定的地址。I/O 控制器通过CPU 提供的地址来判断CPU 要读写的是哪个寄存器。^^","（5）常见I/O 控制方式：","①、^^程序直接控制方式^^：CPU 向I/O 模块发出读写指令，CPU 会从状态寄存器中读取I/O 设备的状态，如果是忙碌状态就继续轮询检查状态，如果是已就绪，就代表I/O 设备已经准备好，可以从中读取数据到CPU 寄存器中，读到CPU 后，CPU 还要往存储器（内存）中写入数据，写完后再执行下一套指令。","②、^^中断驱动方式^^：中断驱动方式的思想是允许I/O 设备主动打断CPU 的运行并请求服务，从而“解放”CPU，使得其向I/O 控制器发送读命令后可以继续做其他有用的工作。","③、^^DMA（直接存储方式）^^：DMA 方式的数据流向是从设备直接放入内存（设备→内存），或者是从内存直接到设备（内存→设备），不再使用CPU 作为中间者。","④、^^通道控制方式^^：通道是一种硬件，可以理解为“低配版的CPU”。通道与CPU 相比的话，CPU 能够处理的指令种类比较多，而通道只能执行单一指令。使用这种控制方式，CPU 干涉频率极低，通道会根据CPU 的指令执行响应程序，只有完成一组数据块的读写后才需要发出中断信号让CPU 干预。"],"title":"","ordered":false},{"h":590,"t":"img","w":1206,"id":"a1-1-3-4-b2","imp":"normal","src":"/kb-assets/theory/p14_r0_98bc357e9ae42d38.png","title":""},{"t":"list","id":"a1-1-3-4-b3","imp":"core","items":["4、==I/O 总线及其发展==：**定义与任务** I/O 总线是计算机用于==在 I/O 设备与内存（主机）之间传输数据的部件==，由传输线路及控制器组成，主要任务是高速传输数据。I/O 总线连接的是 I/O 控制器，I/O 控制器提供 I/O 接口，I/O 接口再连接 I/O 设备。I/O 接口的作用是：连接 I/O 设备自身的控制器，实现 I/O 设备与总线、与主机的连接。 **性能指标** I/O 总线最重要的性能指标是带宽，即单位时间内可传输的最大数据量。总线带宽（MB/s） 数据线宽度（bits）/8 × 总线工作频率（MHz）× 每个总线周期传输数据的次数。","5、I/O 总线带宽","（1）==并行总线带宽(MB/s)=并行总线时钟频率(MHz)*并行总线位宽(bit/8=B)*每时钟传输几组数据(cycle)==","==PCI== 总线位宽是32 位，总线频率33MHz，每时钟传输1 组数据，它的带宽为127.2MB/s，即1017.6Mbps。","==PCI2.1== 总线位宽是64 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为508.6MB/s，即4068.8Mbps。","==AGP== 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。","==AGPPro== 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。","==GPPro== 是AGP 的改进型，它使工作站级主板也能利用AGP 的加速性能，降低了AGP 所需的电压供应，并没有什么太大的改变。","==AGP2X== 总线位宽是32 位，总线频率66MHz，每时钟传输2 组数据，它的带宽为508.6MB/s，即4068.8Mbps。","==AGP4X== 总线位宽是32 位，总线频率66MHz，每时钟传输4 组数据，它的带宽为1017.3MB/s，即8138.4Mbps。","==AGP8X== 总线位宽是32 位，总线频率66MHz，每时钟传输8 组数据，它的带宽为2034.6MB/s，即16276.8Mbps。","==ISA== 总线位宽是16 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为15.9MB/s，即127.2Mbps。","==EISA== 总线位宽是32 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为31.8MB/s，即254.4Mbps。","（2）串行总线","==串行总线带宽(MB/s)=串行总线时钟频率(MHz)*串行总线位宽(bit/8=B)*串行总线管线*编码方式*每时钟传输几组数据(cycle)==","==PCI Express x1== 总线位宽是1 位，总线频率2500MHz，串行总线管线是1 条，每时钟传输2 组数据，编码方式为8b/10b，它的带宽为476.84MB/s，即3814.7Mbps。（带宽是PCI 的3.75 倍）","公式是2500000000(Hz)*1/8(bit)*1(条管线)*8/10(bit)*2(每时钟传输2 组数据)=500000000B/s=476.8371582MB/s，即3814.6972656Mbps。","==PCI Expressx2== 的带宽为953.68MB/s，即7629.4Mbps。（此模式仅用于主板内部接口而非插槽模式）","==PCI Expressx4== 的带宽为1907.36MB/s，即15258.9Mbps。","==PCI Expressx8== 的带宽为3814.72MB/s，即30517.8Mbps。","==PCI Expressx16== 的带宽为7629.44MB/s，即61035.5Mbps。（带宽是AGP8X 的3.75 倍。）","==PCI Expressx32== 的带宽为15258.88MB/s，即122071Mbps。","==注：以下都是理论值，实际上达不到，就像实际网速与带宽一样会有差距。==","6、==主机、外围设备与总线==：^^计算机的主机^^：==CPU、内存储器、总线等==。 计算机的外围设备：外存储器、输入设备、输出设备。","（1）^^总线^^：==提供各部件之间相互交换各种信息的通道==。 总线按连接方式分为：前端总线（CPU 总线），连接内存和 CPU；I/O 总线（PCI 总线），连接内存与 I/O 设备。 总线传输的内容（信号）：数据信号、地址信号、控制信号。","7、==PCI 插槽和PCI-E 插槽(PCI-E x1 和PCI-E x16)==","==一个PCI Express 连接可以被配置成x1，x2，x4，x8，x12，x16 和x32 的数据带宽。x1 的通道能实现单向312.5MB/秒(2.5Gbit/s*1/8 位)的传输速率，同理x32 通道连接就能提供10GB/秒的速率，但考虑使用8b/10b 编码实际上有20%左右的消耗，实际的传输速率大概是8GB/S(x32 单向)。一般的显卡使用的PCI-E X16 标准，数据传输率为4.8GB/S,远远高于现在最流行的AGP 8X 的2.1GB/S 的数据流量。==","（1）==PCI 插槽==：","^^①、工作频率33MHz，^^","^^②、数据线:32 位^^","^^③、传输速率:133MB/s^^","（2）==PCI-E x1 插槽：==","^^①、1 个串行传输通道；^^","^^②、最高传输速率:250MB/s^^","（3）==PCI-E x16 插槽：==","^^①、16 个串行传输通道；^^","^^②、最高传输速率:5GB/s^^"],"title":"","ordered":false},{"h":909,"t":"img","w":1295,"id":"a1-1-3-4-b4","imp":"normal","src":"/kb-assets/theory/p15_r0_269dd9c7cd7a8d1c.png","title":""},{"t":"list","id":"a1-1-3-4-b5","imp":"core","items":["8、==USB 接口==","==（1）通用串行总线式接口==","==（2）高速、可连接多个设备、串行传输==","==（3）传输速率：USB1.1(1.5MB/s)、USB2.0(60MB/s)、USB3.0(625MB/s)、USB3.1(1250MB/s)==","==（4）USB2.0 使用4 线标准连接器；USB3.0 使用6 线标准连接器==","==（5）使用“USB 集线器” 扩展USB 接口，最多可连接127 个设备==","==（6）可通过USB 接口由主机向外设提供电源(＋5V，100～500 mA)==","==（7）USB 支持“即插即用”和“热插拔”。==","==（8）图标：=="],"title":"","ordered":false},{"h":226,"t":"img","w":467,"id":"a1-1-3-4-b6","imp":"normal","src":"/kb-assets/theory/p16_r0_023c65ccdc4c0443.png","title":""},{"t":"list","id":"a1-1-3-4-b7","imp":"core","items":["==（9）可外接设备：打印机、鼠标、键盘、扫描仪等。==","==（10）接口类型：TypeA、TypeB、TypeC 等。=="],"title":"","ordered":false},{"h":639,"t":"img","w":1248,"id":"a1-1-3-4-b8","imp":"normal","src":"/kb-assets/theory/p16_r1_70bbe554ecb0604d.png","title":""},{"t":"list","id":"a1-1-3-4-b9","imp":"core","items":["==（11）使用串口转换工具（器）转串口或并口。==","==（12）相互兼容的。为了向下兼容2.0 版,USB 3.0 采用了9 针脚设计,其中四个针脚和USB 2.0 的形状、定义均完全相同,而另外5 根是专门为USB 3.0 准备的。==","9、==其他接口==","==（1）硬盘常用接口：IDE、SATA(e-SATA)、USB(移动硬盘)等==","==（2）键盘和鼠标常用接口：USB、PS/2 接口等==","==（3）网络接口：RJ-45 接口==","==（4）显示接口：VGA、DVI(24 针)、HDMI（19 针，高清数字音频和视频接口，也称为高清多媒体接口）等==","==（5）串口RS232:可以连接鼠标、投影仪等==","==（6）并口：打印机、扫描仪等。==","==（7）IEEE-1394 接口：串行方式传输，连接大量数据的音、视频设备，采用6 线连接器。==","10、主板常见接口示例图："],"title":"","ordered":false},{"h":907,"t":"img","w":1518,"id":"a1-1-3-4-b10","imp":"normal","src":"/kb-assets/theory/p17_r0_b99e11f30731a9b3.png","title":""},{"t":"callout","id":"a1-1-3-4-b11","imp":"core","kind":"tip","text":"主机与外设通信方式：==程序查询方式（CPU 全程等待效率最低）==、==中断方式（外设就绪打断 CPU）==、==DMA 方式（直接内存访问，外设与主存成批交换数据无需 CPU 介入）==；常用总线接口包括 PCI-Express（主板内部高速点对点）、USB（热插拔串行）、SATA（硬盘串行接口）。","title":"考向复习提示：I/O 操作方式及常用外部总线"},{"t":"callout","id":"a1-1-3-4-b12","imp":"core","kind":"trap","text":"专转本必考趋势：传统早期采用并行接口（如打印机并口 LPT、IDE 硬盘并口）；由于高频时并行多引脚间存在严重的电磁串扰与时钟偏移，==现代高速接口全面转向采用差分信号的高速串行接口（如 PCI-E、SATA、USB、雷电）==；常考判断题误以为“并行传输速率一定快于串行”，结论完全错误！","title":"高频易错陷阱：串行接口 vs 并行接口发展趋势"}]$kbid$::jsonb, $kbidse$A1-1.3.4 I/O 总线，I/O 操作方式，常用的几类 I/O 设备接口，I/O 总线带宽计算。 1、I/O 操作的任务、特点与注意点 1）任务：将输入设备输入的信息送入内存的指定区域，或者将内存指定的内容送出到输出设备。 2）特点： ① I/O 设备速度比 CPU 慢，为提高系统效率，I/O 操作与 CPU 的数据处理操作是并行的； ② 多个 I/O 设备能同时工作（例如一面键盘输入、一面屏幕显示，同时进行打印输出等）； ③ I/O 设备的种类多、性能相差很大，与计算机主机的连接方法也各不相同。 3）注意：每个（类）I/O 设备都有各自专用的控制器，它们的任务是接收 CPU 启动 I/O 操作的命令后，独立地控制 I/O 操作的全过程。 2、I/O 接口 （1）串行：一次传输1 位数据；串行的传输速度不一定小于并行的传输速度.（COM 接口，USB） （2）并行：一次传输8 位（或16 位、32 位）数据。(如LPT 接口打印机或扫描仪、DVI、MIDI、VGA) （3）独占式：只能外接1 个设备（DVI、MIDI 等） （4）总线式：可以扩展多个设备。（USB 等） 3、I/O 控制器 （1）I/O 控制器是用于实现CPU 对设备的控制部件。 （2）I/O 控制器是控制计算机输入输出的一个最基本的控制系统，可指挥计算机的各个部件按照指令的功能要求协调工作的部件。 （3）组成：指令寄存器IR、程序计数器PC、操作控制器OC。 （4）I/O 控制器的功能： ①、接收设备CPU 指令：CPU 的读写指令和参数存储在控制寄存器中 ②、向CPU 报告设备的状态：I/O 控制器中会有相应的状态寄存器，用于记录I/O 设备的当前状态。（比如1 代表设备忙碌，0 代表设备就绪） ③、数据交换：数据寄存器，暂存CPU 发来的数据和设备发来的数据，之后将数据发给控制寄存器或CPU。 ④、地址识别：类似于内存的地址，为了区分设备控制器中的各个寄存器，需要给各个寄存器设置一个特定的地址。I/O 控制器通过CPU 提供的地址来判断CPU 要读写的是哪个寄存器。 （5）常见I/O 控制方式： ①、程序直接控制方式：CPU 向I/O 模块发出读写指令，CPU 会从状态寄存器中读取I/O 设备的状态，如果是忙碌状态就继续轮询检查状态，如果是已就绪，就代表I/O 设备已经准备好，可以从中读取数据到CPU 寄存器中，读到CPU 后，CPU 还要往存储器（内存）中写入数据，写完后再执行下一套指令。 ②、中断驱动方式：中断驱动方式的思想是允许I/O 设备主动打断CPU 的运行并请求服务，从而“解放”CPU，使得其向I/O 控制器发送读命令后可以继续做其他有用的工作。 ③、DMA（直接存储方式）：DMA 方式的数据流向是从设备直接放入内存（设备→内存），或者是从内存直接到设备（内存→设备），不再使用CPU 作为中间者。 ④、通道控制方式：通道是一种硬件，可以理解为“低配版的CPU”。通道与CPU 相比的话，CPU 能够处理的指令种类比较多，而通道只能执行单一指令。使用这种控制方式，CPU 干涉频率极低，通道会根据CPU 的指令执行响应程序，只有完成一组数据块的读写后才需要发出中断信号让CPU 干预。 4、I/O 总线及其发展：定义与任务 I/O 总线是计算机用于在 I/O 设备与内存（主机）之间传输数据的部件，由传输线路及控制器组成，主要任务是高速传输数据。I/O 总线连接的是 I/O 控制器，I/O 控制器提供 I/O 接口，I/O 接口再连接 I/O 设备。I/O 接口的作用是：连接 I/O 设备自身的控制器，实现 I/O 设备与总线、与主机的连接。 性能指标 I/O 总线最重要的性能指标是带宽，即单位时间内可传输的最大数据量。总线带宽（MB/s） 数据线宽度（bits）/8 × 总线工作频率（MHz）× 每个总线周期传输数据的次数。 5、I/O 总线带宽 （1）并行总线带宽(MB/s)=并行总线时钟频率(MHz)*并行总线位宽(bit/8=B)*每时钟传输几组数据(cycle) PCI 总线位宽是32 位，总线频率33MHz，每时钟传输1 组数据，它的带宽为127.2MB/s，即1017.6Mbps。 PCI2.1 总线位宽是64 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为508.6MB/s，即4068.8Mbps。 AGP 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。 AGPPro 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。 GPPro 是AGP 的改进型，它使工作站级主板也能利用AGP 的加速性能，降低了AGP 所需的电压供应，并没有什么太大的改变。 AGP2X 总线位宽是32 位，总线频率66MHz，每时钟传输2 组数据，它的带宽为508.6MB/s，即4068.8Mbps。 AGP4X 总线位宽是32 位，总线频率66MHz，每时钟传输4 组数据，它的带宽为1017.3MB/s，即8138.4Mbps。 AGP8X 总线位宽是32 位，总线频率66MHz，每时钟传输8 组数据，它的带宽为2034.6MB/s，即16276.8Mbps。 ISA 总线位宽是16 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为15.9MB/s，即127.2Mbps。 EISA 总线位宽是32 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为31.8MB/s，即254.4Mbps。 （2）串行总线 串行总线带宽(MB/s)=串行总线时钟频率(MHz)*串行总线位宽(bit/8=B)*串行总线管线*编码方式*每时钟传输几组数据(cycle) PCI Express x1 总线位宽是1 位，总线频率2500MHz，串行总线管线是1 条，每时钟传输2 组数据，编码方式为8b/10b，它的带宽为476.84MB/s，即3814.7Mbps。（带宽是PCI 的3.75 倍） 公式是2500000000(Hz)*1/8(bit)*1(条管线)*8/10(bit)*2(每时钟传输2 组数据)=500000000B/s=476.8371582MB/s，即3814.6972656Mbps。 PCI Expressx2 的带宽为953.68MB/s，即7629.4Mbps。（此模式仅用于主板内部接口而非插槽模式） PCI Expressx4 的带宽为1907.36MB/s，即15258.9Mbps。 PCI Expressx8 的带宽为3814.72MB/s，即30517.8Mbps。 PCI Expressx16 的带宽为7629.44MB/s，即61035.5Mbps。（带宽是AGP8X 的3.75 倍。） PCI Expressx32 的带宽为15258.88MB/s，即122071Mbps。 注：以下都是理论值，实际上达不到，就像实际网速与带宽一样会有差距。 6、主机、外围设备与总线：计算机的主机：CPU、内存储器、总线等。 计算机的外围设备：外存储器、输入设备、输出设备。 （1）总线：提供各部件之间相互交换各种信息的通道。 总线按连接方式分为：前端总线（CPU 总线），连接内存和 CPU；I/O 总线（PCI 总线），连接内存与 I/O 设备。 总线传输的内容（信号）：数据信号、地址信号、控制信号。 7、PCI 插槽和PCI-E 插槽(PCI-E x1 和PCI-E x16) 一个PCI Express 连接可以被配置成x1，x2，x4，x8，x12，x16 和x32 的数据带宽。x1 的通道能实现单向312.5MB/秒(2.5Gbit/s*1/8 位)的传输速率，同理x32 通道连接就能提供10GB/秒的速率，但考虑使用8b/10b 编码实际上有20%左右的消耗，实际的传输速率大概是8GB/S(x32 单向)。一般的显卡使用的PCI-E X16 标准，数据传输率为4.8GB/S,远远高于现在最流行的AGP 8X 的2.1GB/S 的数据流量。 （1）PCI 插槽： ①、工作频率33MHz， ②、数据线:32 位 ③、传输速率:133MB/s （2）PCI-E x1 插槽： ①、1 个串行传输通道； ②、最高传输速率:250MB/s （3）PCI-E x16 插槽： ①、16 个串行传输通道； ②、最高传输速率:5GB/s 8、USB 接口 （1）通用串行总线式接口 （2）高速、可连接多个设备、串行传输 （3）传输速率：USB1.1(1.5MB/s)、USB2.0(60MB/s)、USB3.0(625MB/s)、USB3.1(1250MB/s) （4）USB2.0 使用4 线标准连接器；USB3.0 使用6 线标准连接器 （5）使用“USB 集线器” 扩展USB 接口，最多可连接127 个设备 （6）可通过USB 接口由主机向外设提供电源(＋5V，100～500 mA) （7）USB 支持“即插即用”和“热插拔”。 （8）图标： （9）可外接设备：打印机、鼠标、键盘、扫描仪等。 （10）接口类型：TypeA、TypeB、TypeC 等。 （11）使用串口转换工具（器）转串口或并口。 （12）相互兼容的。为了向下兼容2.0 版,USB 3.0 采用了9 针脚设计,其中四个针脚和USB 2.0 的形状、定义均完全相同,而另外5 根是专门为USB 3.0 准备的。 9、其他接口 （1）硬盘常用接口：IDE、SATA(e-SATA)、USB(移动硬盘)等 （2）键盘和鼠标常用接口：USB、PS/2 接口等 （3）网络接口：RJ-45 接口 （4）显示接口：VGA、DVI(24 针)、HDMI（19 针，高清数字音频和视频接口，也称为高清多媒体接口）等 （5）串口RS232:可以连接鼠标、投影仪等 （6）并口：打印机、扫描仪等。 （7）IEEE-1394 接口：串行方式传输，连接大量数据的音、视频设备，采用6 线连接器。 10、主板常见接口示例图： 考向复习提示：I/O 操作方式及常用外部总线 主机与外设通信方式：程序查询方式（CPU 全程等待效率最低）、中断方式（外设就绪打断 CPU）、DMA 方式（直接内存访问，外设与主存成批交换数据无需 CPU 介入）；常用总线接口包括 PCI-Express（主板内部高速点对点）、USB（热插拔串行）、SATA（硬盘串行接口）。 高频易错陷阱：串行接口 vs 并行接口发展趋势 专转本必考趋势：传统早期采用并行接口（如打印机并口 LPT、IDE 硬盘并口）；由于高频时并行多引脚间存在严重的电磁串扰与时钟偏移，现代高速接口全面转向采用差分信号的高速串行接口（如 PCI-E、SATA、USB、雷电）；常考判断题误以为“并行传输速率一定快于串行”，结论完全错误！$kbidse$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kbid order by node_id loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
